-- ============================================
-- LUMA — Thème 11 : MOYEN 2/3 x4 — Gérer un objet perdu pendant l'événement
-- ============================================


update scenarios set content = '{"characters": {"staff": "le personnel du festival", "stranger": "un festivalier"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(You reach into your pocket for your phone — it''s gone. Panic sets in.)", "text_fr": "(Vous mettez la main dans votre poche pour votre téléphone — il a disparu. La panique s''installe.)", "choices": [{"text": "(Retrace your steps mentally, trying to remember the last time you had it.)", "text_fr": "(Retrace tes pas mentalement, en essayant de te souvenir de la dernière fois que tu l''avais.)", "next": "n2"}, {"text": "(Head straight to the lost and found tent.)", "text_fr": "(Va directement à la tente objets trouvés.)", "next": "n2b"}]}, "n2": {"speaker": "you_thought", "text": "(You remember taking a photo near the main stage about an hour ago.)", "text_fr": "(Vous vous souvenez avoir pris une photo près de la scène principale il y a environ une heure.)", "choices": [{"text": "Head back to the main stage area to search the ground.", "text_fr": "Retourne vers la zone de la scène principale pour chercher au sol.", "next": "n3"}]}, "n2b": {"speaker": "staff", "text": "Lost something? Let''s check what we have here at the lost and found.", "text_fr": "Vous avez perdu quelque chose ? Vérifions ce qu''on a ici aux objets trouvés.", "choices": [{"text": "Yes, my phone — a black one with a cracked case.", "text_fr": "Oui, mon téléphone — un noir avec une coque fissurée.", "next": "n3b"}]}, "n3": {"speaker": "you_thought", "text": "(You search the ground near the main stage, but find nothing among the trampled grass.)", "text_fr": "(Vous cherchez au sol près de la scène principale, mais ne trouvez rien parmi l''herbe piétinée.)", "choices": [{"text": "Ask nearby festival-goers if anyone found a phone.", "text_fr": "Demande aux festivaliers à proximité si quelqu''un a trouvé un téléphone.", "next": "n4"}, {"text": "Check with festival staff about a lost and found service.", "text_fr": "Vérifie auprès du personnel du festival pour un service objets trouvés.", "next": "n4"}]}, "n3b": {"speaker": "staff", "text": "(Checks a box) We do have a black phone here, actually! Cracked case, you said?", "text_fr": "(Vérifie une boîte) On a bien un téléphone noir ici, en fait ! Coque fissurée, vous avez dit ?", "choices": [{"text": "Yes! That could definitely be mine!", "text_fr": "Oui ! Ça pourrait vraiment être le mien !", "next": "n5"}]}, "n4": {"speaker": "stranger", "text": "Actually, I think I saw someone turn in a phone at the info booth earlier!", "text_fr": "En fait, je pense avoir vu quelqu''un remettre un téléphone au stand d''infos plus tôt !", "choices": [{"text": "Thank you so much, I''ll head there right away!", "text_fr": "Merci beaucoup, j''y vais tout de suite !", "next": "n5"}]}, "n5": {"speaker": "staff", "text": "Can you unlock it to confirm it''s yours? We just need to verify ownership.", "text_fr": "Vous pouvez le déverrouiller pour confirmer que c''est le vôtre ? On a juste besoin de vérifier la propriété.", "choices": [{"text": "Of course, here''s my passcode. (Unlocks the phone successfully.)", "text_fr": "Bien sûr, voici mon code. (Déverrouille le téléphone avec succès.)", "next": "n6"}]}, "n6": {"speaker": "staff", "text": "Great, that confirms it! Here you go, someone turned it in about twenty minutes ago.", "text_fr": "Super, ça confirme ! Voici, quelqu''un l''a remis il y a environ vingt minutes.", "choices": [{"text": "That''s such a relief, thank you so much for keeping it safe.", "text_fr": "C''est un tel soulagement, merci beaucoup de l''avoir gardé en sécurité.", "next": "n7"}]}, "n7": {"speaker": "staff", "text": "Of course! Honestly, it happens all the time at festivals like this.", "text_fr": "Bien sûr ! Honnêtement, ça arrive tout le temps dans des festivals comme ça.", "choices": [{"text": "Well, I really appreciate the honesty of whoever found it.", "text_fr": "Bon, j''apprécie vraiment l''honnêteté de celui qui l''a trouvé.", "next": "n8"}]}, "n8": {"speaker": "you_thought", "text": "(Relieved, you check your phone — thankfully, it''s completely undamaged.)", "text_fr": "(Soulagé, vous vérifiez votre téléphone — heureusement, il est complètement intact.)", "choices": [{"text": "Time to get back to enjoying the festival, phone safely in a zipped pocket this time!", "text_fr": "Il est temps de retourner profiter du festival, téléphone bien rangé dans une poche zippée cette fois !", "next": "end_recovered"}]}, "end_recovered": {"speaker": "staff", "text": "Enjoy the rest of the festival! Maybe invest in a phone strap next time, ha!", "text_fr": "Profitez du reste du festival ! Peut-être investir dans une lanière de téléphone la prochaine fois, ha !", "end": true, "ending_label": "Téléphone retrouvé grâce à la gentillesse d''inconnus 📱🙏"}}}'::jsonb, is_playable = true
where title = 'Gérer un objet perdu pendant l''''événement'
  and theme_id = (select id from scenario_themes where position = 11 and language_id = (select id from languages where code = 'en'));
